function maxProfit(prices: number[]): number {
  // Четыре состояния — лучший баланс после каждого этапа:
  // buy1  — купили первую акцию
  // sell1 — продали первую (одна сделка завершена)
  // buy2  — купили вторую
  // sell2 — продали вторую (две сделки завершены)
  let buy1 = -Infinity;
  let sell1 = 0;
  let buy2 = -Infinity;
  let sell2 = 0;

  for (const p of prices) {
    // В каждом состоянии либо ничего не делаем, либо переходим из предыдущего.
    // Порядок обновления не мешает: «купить и продать в тот же день» даёт 0 прибыли
    buy1 = Math.max(buy1, -p); // первая покупка: отдаём p
    sell1 = Math.max(sell1, buy1 + p); // первая продажа: получаем p
    buy2 = Math.max(buy2, sell1 - p); // вторая покупка на деньги после первой сделки
    sell2 = Math.max(sell2, buy2 + p); // вторая продажа
  }

  // sell2 >= sell1 >= 0: одна сделка или ни одной — частные случаи
  return sell2;
}

// Время: O(n)
// Память: O(1)
